<?php namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; class AuthController extends Controller {public function create(){return view('auth.login');} public function store(Request $r){$data=$r->validate(['email'=>'required|email','password'=>'required']); if(!Auth::attempt($data,$r->boolean('remember'))) return back()->withErrors(['email'=>'Email atau kata sandi tidak valid.'])->onlyInput('email'); $r->session()->regenerate(); $r->user()->update(['last_login_at'=>now()]); return redirect()->intended(route('dashboard'));} public function destroy(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');}}
